		t.Errorf("expected 202, got %d", resp.StatusCode)
	}

	// Wait for all retries
	time.Sleep(500 * time.Millisecond)

	// Check stats
	resp, err = http.Get(server.URL + "/webhooks/stats")
	if err != nil {
